let visibleTokens=[];function traceToken(t){const states=new Set(t?.traceStates??[]),edges=new Set(t?.traceEdges??[]);document.querySelectorAll('[data-node]').forEach(el=>el.classList.toggle('trace-highlight',states.has(el.dataset.node)));document.querySelectorAll('[data-edge]').forEach(el=>el.classList.toggle('trace-highlight',edges.has(+el.dataset.edge)))}$('tokens').onpointerover=e=>{const token=e.target.closest('[data-token-index]');if(token&&$('tokens').contains(token))traceToken(visibleTokens[+token.dataset.tokenIndex])};$('tokens').onpointerout=e=>{const token=e.target.closest('[data-token-index]');if(token&&!token.contains(e.relatedTarget))traceToken(null)};$('tokens').onfocusin=e=>{const token=e.target.closest('[data-token-index]');if(token)traceToken(visibleTokens[+token.dataset.tokenIndex])};$('tokens').onfocusout=e=>{if(!e.relatedTarget?.closest('[data-token-index]'))traceToken(null)};function tokenColorClass(name){let hash=0;for(const ch of name)hash=(hash*31+ch.codePointAt(0))>>>0;return 'token-color-'+(hash%10)}
